const { targets, geoCode, device, output, super: useSuper } = $.input;
if (!targets || !targets.length) throw new Error('targets array is required with at least one URL');

const body = { Targets: targets };
if (geoCode) body.GeoCode = geoCode;
if (device) body.Device = device;
if (output && output !== 'raw') body.Output = output;
if (useSuper) body.Super = true;

return { body };

const resp = $.steps.createJob.response || {};
return {
  jobId: resp.JobID || '',
  taskIds: resp.TaskIDs || [],
  message: resp.Message || '',
  targetCount: $.input.targets.length,
  summary: resp.JobID ? `Created scraping job ${resp.JobID} with ${(resp.TaskIDs || []).length} task(s) for ${$.input.targets.length} URL(s)` : 'Failed to create scraping job'
};
